// Typed access to the merged text catalogue generated by `pnpm catalog` (scripts/catalog/build.mjs).
import data from '../data/catalog.json';

export interface Edition {
	/** Stable reference "<source>:<sourceId>", used by introductions (src/content/introductions). */
	ref: string;
	source: string;
	sourceId: string;
	/** Link text naming the source, e.g. "GRETIL", "DSBC देवनागरी", "DSBC (Vol 2)". */
	label: string;
	script: 'iast' | 'deva';
	title: string;
	/** Reader page path segment: "<source>/<sourceId>", see readerUrl(). */
	slug: string;
	/** The Markdown file in the source's meobtis repository (GitHub page). */
	url: string;
	/** The raw Markdown file, fetched by the reader page. */
	rawUrl: string;
	/** The text on the original source website. */
	originalUrl: string;
}

export interface Work {
	title: string;
	titleDeva?: string;
	author?: string;
	/** "group/category", e.g. "sutra/prajnaparamita". */
	category: string;
	/** Heading within the category page, e.g. "Yoginī tantra". */
	section?: string;
	editions: Edition[];
}

export interface Category {
	id: string;
	label: string;
	description: string;
	count: number;
}

export interface Group {
	id: string;
	label: string;
	description: string;
	count: number;
	categories: Category[];
}

export interface Source {
	id: string;
	label: string;
	name: string;
	homepage: string;
	repo: string;
	url: string;
	/** Organisation responsible for the source. */
	publisher: string;
	/** Attribution sentence shown with every edition from this source. */
	credit: string;
	/** Terms of use or licence, and a link to them. */
	terms: string;
	termsUrl: string;
	editions: number;
	works: number;
}

export const catalog = data as unknown as {
	generated: string;
	sources: Source[];
	groups: Group[];
	works: Work[];
};

export const categoryUrl = (group: Group, category: Category) => `/texts/${group.id}/${category.id}/`;

export const worksIn = (group: Group, category: Category) =>
	catalog.works.filter((w) => w.category === `${group.id}/${category.id}`);

export const sourceById = Object.fromEntries(catalog.sources.map((s) => [s.id, s]));

/** URL-safe anchor for a heading. */
export const slugify = (s: string) =>
	s
		.normalize('NFD')
		.replace(/[̀-ͯ]/g, '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-|-$/g, '');

// Display order for tantra classes; other section names sort alphabetically, "Other …" last.
const SECTION_ORDER = [
	'Kriyā tantra',
	'Yoga tantra',
	'Yogottara tantra',
	'Mahāyoga tantra',
	'Yoginī tantra',
	'Anuttarayoga tantra',
	'Advaya tantra',
	'Sahajayāna',
	'Tantric thought',
];

/** Split works into sections for display. Works without a section go under "Other" when other sections exist. */
export function sectionsOf(works: Work[]): { heading?: string; works: Work[] }[] {
	if (!works.some((w) => w.section)) return [{ works }];
	const map = new Map<string, Work[]>();
	for (const w of works) {
		const key = w.section ?? 'Other';
		if (!map.has(key)) map.set(key, []);
		map.get(key)!.push(w);
	}
	const rank = (s: string) => {
		const i = SECTION_ORDER.indexOf(s);
		return i >= 0 ? i : /^other/i.test(s) ? 1000 : 100;
	};
	return [...map.entries()]
		.sort(([a], [b]) => rank(a) - rank(b) || a.localeCompare(b))
		.map(([heading, works]) => ({ heading, works }));
}

/** The page on this site that renders an edition's Markdown. */
export const readerUrl = (e: Edition) => `/read/${e.slug}/`;

/** "group/category" → its group and category records. */
export function categoryOf(work: Work): { group: Group; category: Category } | undefined {
	const [g, c] = work.category.split('/');
	const group = catalog.groups.find((x) => x.id === g);
	const category = group?.categories.find((x) => x.id === c);
	return group && category ? { group, category } : undefined;
}
